def scan_single(sym):
    try:
        df = yf.download(sym, period="1y", interval="1d", progress=False, auto_adjust=True, threads=False)
        if len(df) < 210: return None
        df['EMA50'] = df['Close'].ewm(span=50).mean()
        df['EMA200'] = df['Close'].ewm(span=200).mean()
        for i in range(1, 16):
            if df['EMA50'].iloc[-i-1] < df['EMA200'].iloc[-i-1] and df['EMA50'].iloc[-i] > df['EMA200'].iloc[-i]:
                price = float(df['Close'].iloc[-1])
                sl = float(df['Low'].iloc[-10:].min())*0.98
                slp = (price-sl)/price*100
                if slp>9 or slp<0.3: return None
                return f"💎 {sym.replace('.NS','')} - GOLDEN CROSS {i}d ago ENTRY:{price:.0f} SL:{sl:.0f}({slp:.1f}%) T1:{price*1.15:.0f} T2:{price*1.35:.0f}"
        return None
    except:
        return None

found=[]
with ThreadPoolExecutor(max_workers=12) as ex:
    for r in ex.map(scan_single, STOCKS):
        if r: found.append(r)

if not found:
    msg = "Aaj koi CONFIRM Golden Cross nahi mila [300 Scan] - Bot OK hai"
else:
    msg = f"💥 GOLDEN BOND - {len(found)} SHARES 💥\n\n" + "\n\n".join(found[:40])

